with parsed as (select id, service, level, latency_ms, status_code, payload_json, context, context['region'] as region, get_json_object(payload_json, '$.duration') as duration_text, coalesce(context['region'], 'direct') as region_or_default, coalesce(context['version'], 'none') as version_or_default from app_logs) select case when status_code >= 406 then 'HIGH' else 'LOW' end as status_code_tier, service, sum(status_code) filter (where service = 'auth') as auth_total_status_code, percentile_approx(status_code, 0.5) as status_code_p50, count(*) filter (where service = 'auth') as auth_rows, count(*) filter (where service = 'checkout') as checkout_rows, count(*) as cnt, grouping_id() as grouping_id from parsed group by cube (case when status_code >= 406 then 'HIGH' else 'LOW' end, service) order by auth_rows
